<?php $workPath='/work/project/'.$project['id']; ?>
<div class="topline"><a href="<?= $workPath ?>?tab=pages"><?= e($project['name']) ?> <?= e(t('· Pages')) ?></a><span>v<?= e($page['version']) ?></span></div><header class="page-header"><div><span class="website-kicker"><?= e(t('PROJECT PAGE')) ?></span><h1><?= e($page['title']) ?></h1><p class="muted"><?= e(t('Updated')) ?> <?= e($page['updated_at']) ?></p></div></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<section class="card"><div class="work-markdown"><?= WorkService::markdown($page['body']) ?></div><?php if($page['body']===''): ?><p class="muted"><?= e(t('This page is ready for your notes.')) ?></p><?php endif; ?></section>
<?php if($page['deleted_at']===null): ?><section class="card"><h2><?= e(t('Edit page')) ?></h2><form class="form-grid" method="post" action="<?= $workPath ?>/pages"><?= csrf_field() ?><input type="hidden" name="page_id" value="<?= e($page['id']) ?>"><input type="hidden" name="version" value="<?= e($page['version']) ?>"><label class="full"><?= e(t('Title')) ?><input name="title" maxlength="200" value="<?= e($page['title']) ?>" required></label><label class="full"><?= e(t('Content')) ?><span class="work-editor-toolbar"><button type="button" class="quiet" data-work-format="bold"><?= e(t('Bold')) ?></button><button type="button" class="quiet" data-work-format="heading"><?= e(t('Heading')) ?></button><button type="button" class="quiet" data-work-format="list"><?= e(t('List')) ?></button></span><textarea name="body" maxlength="60000" rows="14" data-work-markdown><?= e($page['body']) ?></textarea></label><label class="work-checkbox full"><input type="checkbox" name="pinned" value="1" <?= $page['pinned']?'checked':'' ?>> <?= e(t('Pin this page')) ?></label><div class="full"><button><?= e(t('Save page')) ?></button></div></form></section><section class="card"><h2><?= e(t('Turn ideas into work')) ?></h2><p class="muted"><?= e(t('Create a work item linked to this page. The page stays in place.')) ?></p><form class="form-grid" method="post" action="<?= $workPath ?>/page/<?= e($page['id']) ?>/issue"><?= csrf_field() ?><label class="full"><?= e(t('Work item title')) ?><input name="title" value="<?= e($page['title']) ?>" maxlength="250" required></label><label class="full"><?= e(t('Description')) ?><textarea name="description" maxlength="30000" rows="4"><?= e(mb_substr($page['body'],0,30000)) ?></textarea></label><div class="full"><button class="secondary"><?= e(t('Create linked work item')) ?></button></div></form><?php foreach($linked as $item): ?><a class="work-compact-issue" href="/work/issue/<?= e($item['id']) ?>"><strong><?= e($project['identifier'].'-'.$item['sequence'].' · '.$item['title']) ?></strong></a><?php endforeach; ?></section><?php endif; ?>
<section class="card"><h2><?= e(t('Page version history')) ?></h2><?php foreach($versions as $version): ?><article class="studio-record-row"><div><strong><?= e(t('Version')) ?> <?= e($version['version']) ?></strong><p class="muted"><?= e($version['created_at']) ?></p></div><?php if((int)$version['version']!==(int)$page['version']&&$page['deleted_at']===null): ?><form method="post" action="<?= $workPath ?>/page/<?= e($page['id']) ?>/rollback" data-confirm="Restore this content as a new page version?"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($page['version']) ?>"><input type="hidden" name="target" value="<?= e($version['version']) ?>"><button class="secondary"><?= e(t('Restore v')) ?><?= e($version['version']) ?></button></form><?php endif; ?></article><?php endforeach; ?></section>
<?php if($page['deleted_at']===null): ?><section class="card"><form method="post" action="<?= $workPath ?>/page/<?= e($page['id']) ?>/trash" data-confirm="Move this project page to Trash? Its content and history will be preserved."><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($page['version']) ?>"><button class="secondary"><?= e(t('Move page to Trash')) ?></button></form></section><?php endif; ?>
